package com.sanchit.passportphoto;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.media.FaceDetector;import android.net.Uri;import android.provider.MediaStore;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;
public class MainActivity extends Activity{
 private ImageView preview;private Bitmap original,result,compareBitmap;private SeekBar brightness,smooth,brush;private Button removeBtn;private boolean removeMode=false;private static final int PICK=10,CAMERA=11,CAM_PERMISSION=12;private static final int BLUE=Color.rgb(74,144,194);
 @Override public void onCreate(Bundle b){super.onCreate(b);buildUi();}
 private TextView text(String s,int sp){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setPadding(16,8,16,8);return t;}private Button button(String s){Button b=new Button(this);b.setText(s);return b;}
 private void buildUi(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(18,18,18,18);TextView title=text("Sanchit Passport Photo V1.0.3",23);title.setGravity(Gravity.CENTER);root.addView(title);root.addView(text("Auto Crop • Edge Cleanup • Compare • Object Remove • बिना AI",13));preview=new ImageView(this);preview.setBackgroundColor(Color.rgb(230,230,230));preview.setScaleType(ImageView.ScaleType.FIT_CENTER);root.addView(preview,new LinearLayout.LayoutParams(-1,0,1));preview.setOnTouchListener((v,e)->handleRemoveTouch(e));LinearLayout source=new LinearLayout(this);Button camera=button("📷 कैमरा");Button pick=button("🖼 फोटो चुनें");source.addView(camera,new LinearLayout.LayoutParams(0,-2,1));source.addView(pick,new LinearLayout.LayoutParams(0,-2,1));root.addView(source);camera.setOnClickListener(v->openCamera());pick.setOnClickListener(v->startActivityForResult(new Intent(Intent.ACTION_PICK,MediaStore.Images.Media.EXTERNAL_CONTENT_URI),PICK));root.addView(text("Fairness / Brightness",13));brightness=new SeekBar(this);brightness.setMax(40);brightness.setProgress(6);root.addView(brightness);root.addView(text("Smooth",13));smooth=new SeekBar(this);smooth.setMax(3);smooth.setProgress(1);root.addView(smooth);LinearLayout tools=new LinearLayout(this);Button compare=button("COMPARE");removeBtn=button("OBJECT REMOVE");tools.addView(compare,new LinearLayout.LayoutParams(0,-2,1));tools.addView(removeBtn,new LinearLayout.LayoutParams(0,-2,1));root.addView(tools);compare.setOnTouchListener((v,e)->{if(result==null||compareBitmap==null)return false;if(e.getAction()==MotionEvent.ACTION_DOWN){preview.setImageBitmap(compareBitmap);return true;}if(e.getAction()==MotionEvent.ACTION_UP||e.getAction()==MotionEvent.ACTION_CANCEL){preview.setImageBitmap(result);return true;}return true;});removeBtn.setOnClickListener(v->{if(result==null){toast("पहले फोटो Process करें");return;}removeMode=!removeMode;removeBtn.setText(removeMode?"REMOVE ON ✓":"OBJECT REMOVE");toast(removeMode?"Background object पर finger चलाएँ":"Object remove बंद");});root.addView(text("Object Remove Brush Size",12));brush=new SeekBar(this);brush.setMax(55);brush.setProgress(24);root.addView(brush);LinearLayout row=new LinearLayout(this);Button process=button("फिर से PROCESS");Button reset=button("RESET");row.addView(process,new LinearLayout.LayoutParams(0,-2,1));row.addView(reset,new LinearLayout.LayoutParams(0,-2,1));root.addView(row);process.setOnClickListener(v->process());reset.setOnClickListener(v->reset());Button save=button("फोटो सेव करें");root.addView(save);save.setOnClickListener(v->save());setContentView(root);}
 private boolean handleRemoveTouch(MotionEvent e){if(!removeMode||result==null)return false;if(e.getAction()!=MotionEvent.ACTION_DOWN&&e.getAction()!=MotionEvent.ACTION_MOVE)return true;float vw=preview.getWidth(),vh=preview.getHeight(),bw=result.getWidth(),bh=result.getHeight();float sc=Math.min(vw/bw,vh/bh),left=(vw-bw*sc)/2f,top=(vh-bh*sc)/2f;float bx=(e.getX()-left)/sc,by=(e.getY()-top)/sc;if(bx<0||by<0||bx>=bw||by>=bh)return true;Canvas c=new Canvas(result);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setColor(BLUE);p.setStyle(Paint.Style.FILL);float rad=Math.max(6,brush.getProgress())/sc;c.drawCircle(bx,by,rad,p);preview.setImageBitmap(result);return true;}
 private void openCamera(){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission("android.permission.CAMERA")!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{"android.permission.CAMERA"},CAM_PERMISSION);return;}Intent i=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);if(i.resolveActivity(getPackageManager())!=null)startActivityForResult(i,CAMERA);else toast("Camera उपलब्ध नहीं है");}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==CAM_PERMISSION&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)openCamera();else if(r==CAM_PERMISSION)toast("Camera permission जरूरी है");}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);try{if(c!=RESULT_OK)return;if(r==PICK&&d!=null){original=MediaStore.Images.Media.getBitmap(getContentResolver(),d.getData());auto();}else if(r==CAMERA&&d!=null&&d.getExtras()!=null){Object o=d.getExtras().get("data");if(o instanceof Bitmap){original=(Bitmap)o;auto();}}}catch(Exception e){toast("Photo error: "+e.getMessage());}}
 private void auto(){brightness.setProgress(6);smooth.setProgress(1);removeMode=false;if(removeBtn!=null)removeBtn.setText("OBJECT REMOVE");process();}
 private void reset(){result=null;compareBitmap=null;original=null;removeMode=false;preview.setImageDrawable(null);brightness.setProgress(6);smooth.setProgress(1);if(removeBtn!=null)removeBtn.setText("OBJECT REMOVE");toast("Reset हो गया — नई फोटो चुनें");}
 private void process(){if(original==null){toast("पहले फोटो लें या चुनें");return;}Bitmap crop=smartCrop(original);int w=700,h=900;Bitmap src=Bitmap.createScaledBitmap(crop,w,h,true);compareBitmap=src.copy(Bitmap.Config.ARGB_8888,false);int[] p=new int[w*h];src.getPixels(p,0,w,0,0,w,h);boolean[] mask=backgroundMask(p,w,h);int add=brightness.getProgress();for(int i=0;i<p.length;i++){int c=p[i];if(mask[i]){if(isBoundary(mask,w,h,i))p[i]=blend(c,BLUE,.18f);else p[i]=BLUE;continue;}int r=Color.red(c),g=Color.green(c),b=Color.blue(c);r=clamp((int)(r*1.010f)+add);g=clamp((int)(g*1.010f)+add);b=clamp((int)(b*1.006f)+add);p[i]=Color.rgb(r,g,b);}Bitmap out=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);out.setPixels(p,0,w,0,0,w,h);if(smooth.getProgress()>0)out=softSmooth(out,smooth.getProgress());result=out;removeMode=false;if(removeBtn!=null)removeBtn.setText("OBJECT REMOVE");preview.setImageBitmap(result);toast("V1.0.3 Auto Process तैयार");}
 private int blend(int original,int bg,float keep){int r=(int)(Color.red(original)*keep+Color.red(bg)*(1-keep)),g=(int)(Color.green(original)*keep+Color.green(bg)*(1-keep)),b=(int)(Color.blue(original)*keep+Color.blue(bg)*(1-keep));return Color.rgb(clamp(r),clamp(g),clamp(b));}
 private boolean isBoundary(boolean[] m,int w,int h,int id){int x=id%w,y=id/w;if(x<1||y<1||x>=w-1||y>=h-1)return false;for(int yy=-1;yy<=1;yy++)for(int xx=-1;xx<=1;xx++)if(!m[(y+yy)*w+x+xx])return true;return false;}
 private boolean[] backgroundMask(int[] p,int w,int h){boolean[] out=edgeFlood(p,w,h);for(int pass=0;pass<2;pass++){boolean[] next=out.clone();for(int y=1;y<h-1;y++)for(int x=1;x<w-1;x++){int id=y*w+x;if(out[id])continue;int neighbors=0;for(int yy=-1;yy<=1;yy++)for(int xx=-1;xx<=1;xx++)if((xx!=0||yy!=0)&&out[(y+yy)*w+x+xx])neighbors++;if(neighbors>=5&&isChromaBackground(p[id]))next[id]=true;}out=next;}return out;}
 private boolean[] edgeFlood(int[] p,int w,int h){boolean[] seen=new boolean[p.length],mask=new boolean[p.length];int[] avg=dominantBorder(p,w,h);int rr=avg[0],gg=avg[1],bb=avg[2];ArrayDeque<Integer> q=new ArrayDeque<>();for(int x=0;x<w;x++){addSeed(q,seen,p,x,rr,gg,bb);addSeed(q,seen,p,(h-1)*w+x,rr,gg,bb);}for(int y=0;y<h;y++){addSeed(q,seen,p,y*w,rr,gg,bb);addSeed(q,seen,p,y*w+w-1,rr,gg,bb);}int[] dx={1,-1,0,0},dy={0,0,1,-1};while(!q.isEmpty()){int id=q.remove();mask[id]=true;int x=id%w,y=id/w;for(int k=0;k<4;k++){int nx=x+dx[k],ny=y+dy[k];if(nx<0||ny<0||nx>=w||ny>=h)continue;int ni=ny*w+nx;if(!seen[ni]&&similarBg(p[ni],rr,gg,bb)){seen[ni]=true;q.add(ni);}}}return mask;}
 private int[] dominantBorder(int[] p,int w,int h){int[] count=new int[512],sr=new int[512],sg=new int[512],sb=new int[512];int step=3;for(int x=0;x<w;x+=step){acc(p[x],count,sr,sg,sb);acc(p[(h-1)*w+x],count,sr,sg,sb);}for(int y=0;y<h;y+=step){acc(p[y*w],count,sr,sg,sb);acc(p[y*w+w-1],count,sr,sg,sb);}int best=0;for(int i=1;i<512;i++)if(count[i]>count[best])best=i;int n=Math.max(1,count[best]);return new int[]{sr[best]/n,sg[best]/n,sb[best]/n};}
 private void acc(int c,int[] count,int[] sr,int[] sg,int[] sb){int r=Color.red(c),g=Color.green(c),b=Color.blue(c),bin=(r>>5)*64+(g>>5)*8+(b>>5);count[bin]++;sr[bin]+=r;sg[bin]+=g;sb[bin]+=b;}
 private void addSeed(ArrayDeque<Integer> q,boolean[] seen,int[] p,int id,int r,int g,int b){if(!seen[id]&&similarBg(p[id],r,g,b)){seen[id]=true;q.add(id);}}
 private boolean similarBg(int c,int r,int g,int b){int cr=Color.red(c),cg=Color.green(c),cb=Color.blue(c),mx=Math.max(cr,Math.max(cg,cb));if(mx<105&&!isChromaBackground(c))return false;int dr=cr-r,dg=cg-g,db=cb-b;double d=Math.sqrt(dr*dr+dg*dg+db*db);return d<54||isChromaBackground(c);}
 private boolean isChromaBackground(int c){int r=Color.red(c),g=Color.green(c),b=Color.blue(c);int max=Math.max(r,Math.max(g,b)),min=Math.min(r,Math.min(g,b));boolean green=g>88&&g>r*1.15&&g>b*.95&&(max-min)>28;boolean cyan=g>95&&b>95&&r<Math.min(g,b)*.78&&(max-min)>28;boolean paleGreen=g>145&&g>r*1.07&&g>b*.95&&(g-r)>16;return green||cyan||paleGreen;}
 private int clamp(int v){return Math.max(0,Math.min(255,v));}
 private Bitmap softSmooth(Bitmap s,int level){int w=s.getWidth(),h=s.getHeight();int[] a=new int[w*h],o=new int[w*h];s.getPixels(a,0,w,0,0,w,h);System.arraycopy(a,0,o,0,a.length);float blend=Math.min(.15f,.05f*level);for(int y=1;y<h-1;y++)for(int x=1;x<w-1;x++){int id=y*w+x,c=a[id],r=Color.red(c),g=Color.green(c),b=Color.blue(c);if(b>r*1.18&&b>g*.95)continue;int ar=0,ag=0,ab=0;for(int yy=-1;yy<=1;yy++)for(int xx=-1;xx<=1;xx++){int z=a[(y+yy)*w+x+xx];ar+=Color.red(z);ag+=Color.green(z);ab+=Color.blue(z);}ar/=9;ag/=9;ab/=9;o[id]=Color.rgb(clamp((int)(r*(1-blend)+ar*blend)),clamp((int)(g*(1-blend)+ag*blend)),clamp((int)(b*(1-blend)+ab*blend)));}Bitmap d=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);d.setPixels(o,0,w,0,0,w,h);return d;}
 private Bitmap smartCrop(Bitmap b){try{int ow=b.getWidth(),oh=b.getHeight();int dw=Math.min(1000,ow);float scale=(float)dw/ow;int dh=Math.max(2,(int)(oh*scale));if((dw&1)==1)dw--;Bitmap small=Bitmap.createScaledBitmap(b,dw,dh,true).copy(Bitmap.Config.RGB_565,false);FaceDetector fd=new FaceDetector(small.getWidth(),small.getHeight(),1);FaceDetector.Face[] fs=new FaceDetector.Face[1];if(fd.findFaces(small,fs)>0&&fs[0]!=null){PointF m=new PointF();fs[0].getMidPoint(m);float inv=(float)ow/small.getWidth(),cx=m.x*inv,eyesY=m.y*inv,eye=fs[0].eyesDistance()*inv;float cw=Math.max(eye*5.5f,ow*.36f);cw=Math.min(cw,ow);float ch=cw*9f/7f;if(ch>oh){ch=oh;cw=ch*7f/9f;}float left=cx-cw/2f,top=eyesY-ch*.40f;left=Math.max(0,Math.min(left,ow-cw));top=Math.max(0,Math.min(top,oh-ch));return Bitmap.createBitmap(b,Math.round(left),Math.round(top),Math.round(cw),Math.round(ch));}}catch(Exception ignored){}return crop79(b);}
 private Bitmap crop79(Bitmap b){int w=b.getWidth(),h=b.getHeight();float t=7f/9f;int nw=w,nh=h;if((float)w/h>t)nw=(int)(h*t);else nh=(int)(w/t);return Bitmap.createBitmap(b,(w-nw)/2,(h-nh)/2,nw,nh);}
 private void save(){if(result==null){toast("पहले फोटो तैयार करें");return;}try{ContentValues v=new ContentValues();v.put(MediaStore.Images.Media.DISPLAY_NAME,"Sanchit_Passport_"+System.currentTimeMillis()+".jpg");v.put(MediaStore.Images.Media.MIME_TYPE,"image/jpeg");if(Build.VERSION.SDK_INT>=29)v.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/Sanchit Passport Photo");Uri u=getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,v);OutputStream os=getContentResolver().openOutputStream(u);result.compress(Bitmap.CompressFormat.JPEG,97,os);os.close();toast("फोटो सेव हो गई");}catch(Exception e){toast("Save error: "+e.getMessage());}}
 private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
}